import express from 'express';
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { randomUUID } from 'node:crypto';

const __dirname = dirname(fileURLToPath(import.meta.url));
const dataPath = join(__dirname, 'books.json');

const app = express();
const port = process.env.PORT || 3000;

app.set('view engine', 'ejs');
app.set('views', join(__dirname, 'views'));
app.use(express.urlencoded({ extended: true }));
app.use(express.static(join(__dirname, 'public')));

async function loadBooks() {
  try {
    const raw = await readFile(dataPath, 'utf-8');
    return JSON.parse(raw);
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

async function saveBooks(books) {
  await writeFile(dataPath, JSON.stringify(books, null, 2));
}

app.get('/', async (req, res) => {
  const books = await loadBooks();
  const reading = books.filter(b => !b.finished);
  const finished = books.filter(b => b.finished);
  res.render('index', { reading, finished });
});

app.get('/books/new', (req, res) => {
  res.render('new');
});

app.post('/books', async (req, res) => {
  const { title, author, notes } = req.body;
  const books = await loadBooks();
  const book = {
    id: randomUUID(),
    title: title?.trim(),
    author: author?.trim(),
    notes: notes?.trim(),
    finished: false,
    createdAt: new Date().toISOString(),
  };
  books.unshift(book);
  await saveBooks(books);
  res.redirect('/');
});

app.get('/books/:id', async (req, res) => {
  const books = await loadBooks();
  const book = books.find(b => b.id === req.params.id);
  if (!book) return res.status(404).send('Book not found');
  res.render('book', { book });
});

app.post('/books/:id/finish', async (req, res) => {
  const books = await loadBooks();
  const book = books.find(b => b.id === req.params.id);
  if (!book) return res.status(404).send('Book not found');
  book.finished = true;
  book.finishedAt = new Date().toISOString();
  await saveBooks(books);
  res.redirect('/');
});

app.listen(port, () => {
  console.log(`Books app listening on http://localhost:${port}`);
});

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  max-width: 680px;
  margin: 0 auto;
  padding: 2rem 1rem;
  line-height: 1.5;
  color: #222;
}

h1, h2, h3 {
  margin-top: 0;
}

a {
  color: #1d4ed8;
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

.actions {
  margin: 1rem 0 2rem;
}

.button {
  display: inline-block;
  padding: 0.5rem 1rem;
  background: #1d4ed8;
  color: #fff;
  border-radius: 0.375rem;
  border: none;
  cursor: pointer;
  font-size: 1rem;
}

.button:hover {
  background: #1e40af;
  text-decoration: none;
}

.button.secondary {
  background: #6b7280;
}

.button.secondary:hover {
  background: #4b5563;
}

.book-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.book-list li {
  border: 1px solid #e5e7eb;
  border-radius: 0.5rem;
  padding: 1rem;
  margin-bottom: 1rem;
}

.book-list h3 {
  margin-bottom: 0.25rem;
}

.meta {
  color: #6b7280;
  font-size: 0.95rem;
}

.book-list form {
  margin-top: 0.75rem;
}

label {
  display: block;
  margin: 1rem 0 0.25rem;
  font-weight: 500;
}

input[type='text'],
textarea {
  width: 100%;
  padding: 0.5rem;
  border: 1px solid #d1d5db;
  border-radius: 0.375rem;
  font-size: 1rem;
  box-sizing: border-box;
}

textarea {
  min-height: 8rem;
  resize: vertical;
}

.book-detail .notes {
  white-space: pre-wrap;
  background: #f9fafb;
  padding: 1rem;
  border-radius: 0.5rem;
  border: 1px solid #e5e7eb;
}

.empty {
  color: #6b7280;
  font-style: italic;
}

.back {
  display: block;
  margin-bottom: 1rem;
}

